    static final class Ring {
        final int country;
        final float[] coordinates;
        Ring(int country, float[] coordinates) {
            this.country = country;
            this.coordinates = coordinates;
        }
    }

    static final List<Ring> RINGS = decode();

    static int findCountry(String label) {
        String key = normalize(label);
        if (key.isEmpty()) return -1;
        if (key.equals("us") || key.equals("usa") || key.equals("unitedstates")) key = "unitedstatesofamerica";
        if (key.equals("uk") || key.equals("greatbritain")) key = "unitedkingdom";
        if (key.equals("russia")) key = "russianfederation";
        if (key.equals("southkorea")) key = "republicofkorea";
        if (key.equals("northkorea")) key = "democraticpeoplesrepublicofkorea";
        if (key.equals("iran")) key = "islamicrepublicofiran";
        if (key.equals("syria")) key = "syrianarabrepublic";
        if (key.equals("bolivia")) key = "plurinationalstateofbolivia";
        if (key.equals("venezuela")) key = "bolivarianrepublicofvenezuela";
        if (key.equals("tanzania")) key = "unitedrepublicoftanzania";
        for (int i = 0; i < COUNTRY_NAMES.length; i++) {
            if (normalize(COUNTRY_NAMES[i]).equals(key)) return i;
        }
        for (int i = 0; i < COUNTRY_NAMES.length; i++) {
            String candidate = normalize(COUNTRY_NAMES[i]);
            if (candidate.startsWith(key) || key.startsWith(candidate)) return i;
        }
        return -1;
    }

    private static String normalize(String value) {
        if (value == null) return "";
        return value.toLowerCase(java.util.Locale.ROOT).replaceAll("[^a-z0-9]", "");
    }

    private static List<Ring> decode() {
        StringBuilder joined = new StringBuilder();
        for (String part : ENCODED) joined.append(part);
        byte[] data = Base64.decode(joined.toString(), Base64.DEFAULT);
        ArrayList<Ring> result = new ArrayList<>();
        int offset = 0;
        while (offset + 3 <= data.length) {
            int country = data[offset++] & 0xff;
            int count = ((data[offset++] & 0xff) << 8) | (data[offset++] & 0xff);
            if (count < 3 || offset + count * 4 > data.length) break;
            float[] coordinates = new float[count * 2];
            for (int i = 0; i < count * 2; i++) {
                int value = (short)(((data[offset] & 0xff) << 8) | (data[offset + 1] & 0xff));
                offset += 2;
                coordinates[i] = value / 100f;
            }
            result.add(new Ring(country, coordinates));
        }
        return result;
    }
